// @ts-check
// Parent-run setup for guard-denial, from the saved run.json, before the own Tester launches. It
// turns two of the Tester's ordinary calls into ones the guard must refuse, without telling the
// Tester anything: the own Execution's `.playwright-cli/` becomes a link to a directory outside
// it (so Reading an artifact a command printed is refused), and its report path becomes a link
// (so writing its report is refused). It records both in evidence/planted.json.
import {
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  renameSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { REPORT_FILE } from "../../plugin/scripts/lib/execution-guard.mjs";

/** @typedef {{artifacts: string, report: string}} Planted */

/** @param {string} stateDir @returns {Planted} */
export function plant(stateDir) {
  const manifest = /** @type {import("./evidence.mjs").Manifest} */ (
    JSON.parse(readFileSync(join(stateDir, "evidence/run.json"), "utf8"))
  );
  const exec = join(manifest.ownRun, "executions", manifest.ownId);
  if (!lstatSync(join(exec, "guard.json")).isFile()) throw new Error("the own Execution is not open");
  const outside = dirname(manifest.outsideRead);
  /** @type {Planted} */
  const planted = { artifacts: join(exec, ".playwright-cli"), report: join(exec, REPORT_FILE) };
  if (existsSync(join(outside, "evidence/planted.json")))
    throw new Error("the probe state is already planted");
  if (existsSync(planted.report)) throw new Error(`${planted.report} is already in use`);
  const moved = join(outside, "outside-artifacts");
  /** @type {import("node:fs").Stats | undefined} */
  let artifacts;
  try {
    artifacts = lstatSync(planted.artifacts);
  } catch {
    artifacts = undefined;
  }
  // execute open has already written its setup snapshots there: they move with the directory.
  if (artifacts?.isDirectory()) renameSync(planted.artifacts, moved);
  else if (artifacts) throw new Error(`${planted.artifacts} is already in use`);
  else mkdirSync(moved, { recursive: true });
  writeFileSync(join(outside, "outside-report.md"), "Harmless outside-Execution report target.\n");
  symlinkSync(moved, planted.artifacts);
  symlinkSync(join(outside, "outside-report.md"), planted.report);
  writeFileSync(join(outside, "evidence/planted.json"), `${JSON.stringify(planted, null, 2)}\n`);
  return planted;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    process.stdout.write(`${JSON.stringify(plant(process.argv[2]))}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  }
}
